public class BoardScript : MonoBehaviour
{
    public GameObject[] tiles; // Array de objetos (gemas) en el grid
    public int gridSizeX = 5;
    public int gridSizeY = 5;

    void Start()
    {
        // Inicializa el juego
        CreateGrid();
    }

    void CreateGrid()
    {
        // Crea un grid de objetos (gemas) en el board
        for (int x = 0; x < gridSizeX; x++)
        {
            for (int y = 0; y < gridSizeY; y++)
            {
                GameObject tile = Instantiate(tiles[Random.Range(0, tiles.Length)], new Vector3(x, y, 0), Quaternion.identity);
                tile.GetComponent<TileScript>().x = x;
                tile.GetComponent<TileScript>().y = y;
            }
        }
    }

    void SwapTiles(int x1, int y1, int x2, int y2)
    {
        // Intercambia dos objetos en el grid
        GameObject tile1 = GetTile(x1, y1);
        GameObject tile2 = GetTile(x2, y2);

        // Intercambia los objetos
        tile1.transform.position = tile2.transform.position;
        tile2.transform.position = tile1.transform.position;
    }

    GameObject GetTile(int x, int y)
    {
        // Devuelve un objeto en el grid
        foreach (GameObject tile in tiles)
        {
            if (tile.GetComponent<TileScript>().x == x && tile.GetComponent<TileScript>().y == y)
            {
                return tile;
            }
        }
        return null;
    }

