    showSearchResults(results);
  } catch (error) {
    if (error.name === 'InvalidQuery') {
      displaySearchError('Invalid query. Please try again.');
    } else {
      displaySearchError('Error searching. Please try again.');
    }
  }
});

function showSearchResults(results) {
  searchResults.innerHTML = results;
  searchResults.classList.add('show');
  searchResults.classList.remove('hide');
}

function hideSearchResults() {
  searchResults.innerHTML = '';
  searchResults.classList.add('hide');
  searchResults.classList.remove('show');
}

function displaySearchError(message) {
  searchError.innerHTML = message;
  searchError.classList.add('show');
  searchError.classList.remove('hide');
}
